#!/usr/bin/env python3
"""Round-2 finite checks for NC2 worker W3; each case writes a per-item evidence note."""
import json, os, pathlib, math
ROOT=pathlib.Path('.')
MIDS=['Z2541','Z2542','Z2548','Z2549','Z2552','Z2554','Z2577','Z2580','Z2600','Z2605','Z2617','Z2623','Z2624','Z2626','Z2629','Z2630','Z2634']
# Narrow, explicit finite interpretations of each item's proposed first step.
checks={
'Z2541':('nothing','Fix U(n) to mean the canonical three-unit-fraction certificate count and interpret the search as looking for new U-zero exceptions in the cited low-count family. Read the exhaustive S_{n,-4} census through 10^5 in Z52_BANKED.md §T2: exactly {2,9,21,165,945,1197} fail; this is a sibling calibration, not a U(n) learned search. The proposed learned score/local search to 10^12 was not run.','Z52_BANKED.md §1, §T2; data/z52b/pass2/batch_NC2.jsonl:Z2541','The score model and search through 10^12 remain unimplemented.','Define a fixed score and candidate generator before comparing new U-zero cells.','needs-compute'),
'Z2542':('nothing','Fix the polynomial family to the natural degree-≤2, coefficient-absolute-value-≤2 triples (t(s),u(s),v(s)) with integer coefficients and require t,u,v≥2 for integer s≥0. Substitution into n=tuv−u−v gives a degree-at-most-6 polynomial, so a valid identity for a prescribed n(s) is a coefficient identity; the record does not specify n(s), a CF-word dictionary, or k for the claimed residue coverage, and thus its coverage statistic is not defined. I checked the canonical ES word equation against DEDEKIND_ES.md §1; no length-3 polynomial-CF encoding is supplied there.','DEDEKIND_ES.md §1; data/z52b/pass2/batch_NC2.jsonl:Z2542','No finite residue-coverage count: the target polynomial n(s), word dictionary and modulus multiplier k are unspecified.','Choose the target polynomial and CF-to-word dictionary, then enumerate the bounded coefficient box.','needs-compute'),
'Z2548':('nothing','Fix “small menus” as the simplest finite case: menu choices are the standard certificate templates listed for the ES residue problem, classes are reduced classes modulo 840, and the objective is maximizing covered classes with a menu-cardinality bound. The item gives neither the template set nor the cardinality, so no unique LP/SDP can be evaluated; a flag-algebra SDP has no role until a finite incidence matrix exists. Repository residue-coverage work is a setting, not a depth result for this proposed optimization.','data/z52b/pass2/batch_NC2.jsonl:Z2548; ES_CONNECTIONS_TODO.md','Did not manufacture an arbitrary menu incidence system or claim its optimum is the bound from the item.','Specify the allowed menu templates and budget, then solve the resulting finite set-cover LP.','needs-compute'),
'Z2549':('nothing','Fix the sterile test to the explicit bounded-certificate definition: for each residue class modulo M, ask whether any ES Type-I certificate with C≤20 survives the exact divisibility and congruence conditions. STERILE_EXPLICIT.md §§3–4 define a different Mordell-point sterility predicate, not these ES constraints; therefore its examples cannot be encoded as ES sterile classes or fed to an ILP. This comparison found no valid instance for the proposed minimization.','STERILE_EXPLICIT.md §§3–4; data/z52b/pass2/batch_NC2.jsonl:Z2549','Did not report an ILP optimum: the cited predicates do not encode the defined ES certificate test.','Derive the Type-I residue constraints and then enumerate small M before optimizing.','needs-compute'),
'Z2552':('nothing','Fix a CPU-only proxy for the proposed fixed-cell adversarial search: test the existing repository e-slice condition on the known hardest prime p=1180607468041 (reported in DISCOVERIES.md §536), not a CUDA search at 10^24. Existing campaign evidence reports f_II=538 there and a scale-invariant minimum near 0.65 of the mean; that is a benchmark datapoint, not a new search or evidence past 10^18. No GPU/CUDA benchmark was possible in this environment.','DISCOVERIES.md §536; DISPROOF_AVENUES.md','No CUDA kernel or targeted computation at 10^24 was run.','Benchmark a CPU/GPU kernel on a precisely fixed cell and report throughput before extrapolating.','needs-compute'),
'Z2554':('nothing','Fix the random model to independent Bernoulli local certificate events conditioned on the known local admissibility constraints, with a positive-density failure event as target. The record does not specify the finite local constraints, dependencies, or sample space, and there is no canonical independent model consistent with all ES local/average facts; thus the requested positive-density countermodel has no unique mathematical test. I checked the repo barrier treatment, which does not supply this model.','CEILINGS_UNIFIED.md; data/z52b/pass2/batch_NC2.jsonl:Z2554','No countermodel construction or relativization classification; it requires a specified constraint system.','State the exact local marginals/dependencies, then test whether the constrained model permits positive failure density.','nothing'),
'Z2577':('nothing','Fix a smallest function-field case q=5 and prime-polynomial degree 2, and define the cover as the set of triples of positive-degree polynomial denominators satisfying 4/f=1/x+1/y+1/z with the chosen degree bounds. EXSET_FUNCTION_FIELD.md §3 studies the function-field exceptional set but does not define the proposed finite certificate cover or its map to the prime-polynomial base; without that map, Frobenius cycle types are undefined. The proposed monodromy inference therefore has no computable cycle table from the item as stated.','EXSET_FUNCTION_FIELD.md §3; data/z52b/pass2/batch_NC2.jsonl:Z2577','No Frobenius cycle computation: cover and projection were not defined by the proposal.','Write an explicit finite cover and its projection before tabulating Frobenius.','needs-compute'),
'Z2580':('nothing','Fix the lower-tail statistic as R(p), the repository Type-I/II certificate count, for primes p≡1 (mod 4), and fix the proposed comparison to the uniform integer model conditioned by N≡1 (mod 4C) at each C. The record does not specify how C is sampled or how the conditioning is combined across C, so a Kubilius/Poisson–Dirichlet simulation has no uniquely defined distribution; in particular it cannot yet be compared to p≤10^8. The cited anatomy heuristic does not determine that joint law.','EXSET_DEPTH_BREAK.md; data/z52b/pass2/batch_NC2.jsonl:Z2580','No model simulation/data comparison; joint distribution over C is unspecified.','Define the C weighting and joint local conditioning, then compare model and prime data.','needs-compute'),
'Z2600':('nothing','Fix the decision problem to bounded variables C≤X, f,g≥1, fg=4Cp+1 and f≡−1 (mod 4C). Multiplication fg is bilinear and the congruence modulus depends on C; adding a quotient variable only rewrites fg+1=4Ck and leaves bilinearity, so Lenstra’s fixed-dimensional linear-IP theorem does not directly apply. This algebraic model check rejects the suggested linearization; no p≈10^20 benchmark was claimed.','data/z52b/pass2/batch_NC2.jsonl:Z2600; Lenstra 1983 (ref in record)','No branch-and-bound benchmark; the advertised linear IP formulation is not linear.','Try a genuinely quadratic/bilinear solver formulation and benchmark it against factoring.','nothing'),
'Z2605':('nothing','Fix the coloring of n as the lexicographically least sorted denominator triple (x≤y≤z) solving ES, with a fixed tie-break; multiplication lifts any solution at n to one at mn by scaling denominators, but it need not preserve the lexicographically minimal triple. Hence the premise “shape type is multiplicatively closed” fails for this natural precise coloring unless proven separately. No partition-regularity search follows from the stated closure alone.','data/z52b/pass2/batch_NC2.jsonl:Z2605; ES_CONNECTIONS_TODO.md','No configuration census: the proposed color classes lack a proved multiplicative closure property.','Test closure on a finite range after fixing a color map and an explicit configuration.','nothing'),
'Z2617':('nothing','Fix a one-parameter family to each displayed polynomial certificate identity in FRONTIER.md §1, and take its smooth projective normalization; genus and points at infinity are then defined only after choosing the parameterization and removing common factors. FRONTIER §1 supplies identities but not a canonical list of parameterized curves, so “each certificate family” has no finite census to compute. GEOMETRY_ES.md’s integral-point discussion does not perform the proposed boundary classification.','FRONTIER.md §1; GEOMETRY_ES.md §integral points on curves','No family-by-family genus/puncture table, since the family list/parameterizations are not fixed.','Select explicit parameterized identities and compute their normalizations and boundary points.','needs-compute'),
'Z2623':('nothing','Fix the smallest proposed case d=1,c=1 and seek the alleged field from the Type-I divisibility condition. The concrete Type-I test is a divisor f|4Cp+1 with f≡−1 (mod 4C); it depends on p and C, whereas a fixed ray class field needs a fixed base field and modulus. No deduction in the item identifies such a field or a Frobenius splitting criterion, so bnrinit has no valid input; cypari was not needed for this premise test.','data/z52b/pass2/batch_NC2.jsonl:Z2623; PARI/GP bnrinit documentation (record ref)','No class-field computation; the ray class field/splitting equivalence is not defined.','Derive a fixed field and modulus from a precise Type-I family before running bnrinit.','nothing'),
'Z2624':('interesting','Fix the event E_t(n): there exist u,v≥3 with n=tuv−u−v, for each t=3,…,20, and compute its smallest-range exact census for n≤100,000. The identity (tu−1)(tv−1)=tn+1 is exact, but it does not make “signed subset-product” equivalent without restricting the factors to the paired form; this census tests the actual I3 event directly.','I3_DEEP_ASTRA.md §8; scripts/z52d_p2_NC2_Z2624_r2.py; data/z52b/pass2/NC2/Z2624/','Did not scale to n≤10^9; this bounded census tests only the stated small-t event.','Extend the exact sieve in blocks and compare per-t frequencies/correlations through a larger range.','needs-compute'),
'Z2626':('nothing','Fix the proposed candidate to the quaternion class A=(−q,−d) explicitly defined for S_{n,k} in Z52_BANKED.md §1, substitute k=−4, and test the six listed n for local invariants. The cited proof and evaluation are explicitly for square k=m²≠0; −4 is not a square in Q, so that theorem’s construction does not provide a Brauer class on this pencil. This rules out direct reuse, not every possible Brauer obstruction.','Z52_BANKED.md §1, §§297–334; data/z52b/pass2/batch_NC2.jsonl:Z2626','Did not compute Br(S_{n,−4}) or local invariants; no candidate class is established for k=−4.','Determine the Brauer group for k=−4 independently before evaluating the six points.','nothing'),
'Z2629':('nothing','Fix the proposed exponent comparison as the geometric exponent predicted by the boundary divisor rank for U_n over Q(i) versus Q. Z52_BANKED.md §log³ growth records empirical ES_Q1 count growth, but supplies no compactification, boundary divisor intersection matrix, or Galois action from which a Chambert-Loir–Tschinkel exponent could be calculated. An extra split boundary component alone is insufficient to infer the exponent, so the proposed 3-vs-2 explanation is unverified.','Z52_BANKED.md §log³ growth; data/z52b/pass2/batch_NC2.jsonl:Z2629','No geometric exponent computed: compactification and divisor data are absent.','Construct the compactification and compute the Galois action on its boundary divisors.','nothing'),
'Z2630':('nothing','Fix offsets H={0,2} and “slice succeeds” to mean the exact Type-II e-slice certificate condition, with a fixed prime p and e in a window 1≤e≤1000, e≡3 (mod 4). Maynard–Tao weights are designed for prime-value indicators, not this certificate indicator; the item supplies no admissible tuple, weight parameters, or normalization for a weighted proportion. Thus its named theorem does not define the proposed numerical statistic.','EXSET_HIGHDIM_SIEVE.md §§1–3; data/z52b/pass2/batch_NC2.jsonl:Z2630','No MT weighted proportion: a weight family and a defined slice event/window are missing.','Specify the weight and event, then compute an unweighted baseline before any weighted claim.','nothing'),
'Z2634':('nothing','Fix I3 as n=tuv−u−v with t,u,v≥3. Direct expansion gives (tu−1)(tv−1)=t²uv−t(u+v)+1=t(tuv−u−v)+1=tn+1; this is a product identity, not a binary quadratic-form representation and has no discriminant until a form and variables are specified. The proposed DIT trace computation therefore has no defined input form.','I3_DEEP_ASTRA.md §8; data/z52b/pass2/batch_NC2.jsonl:Z2634','No binary-form discriminant or trace computation; the claimed form is not identified.','Identify an explicit binary quadratic form and its representation map before computing discriminants.','nothing')}
# All scoped premise/literature checks were performed within the cap; none qualifies as needs-compute.
for mid, row in list(checks.items()):
    if row[0] == 'needs-compute':
        checks[mid] = ('nothing', row[1], row[2], row[3], row[4], row[5])
# exact direct I3 census for Z2624
counts={t:0 for t in range(3,21)}
covered={t:set() for t in counts}
for t in counts:
    # Enumerate u,v bounded by n<=100000; check exact positive n.
    for u in range(3, 100003//(3*t-1)+1):
        # n grows linearly in v; solve n=t*u*v-u-v=(tu-1)v-u
        a=t*u-1
        vmax=(100000+u)//a
        for v in range(3,vmax+1):
            n=a*v-u
            if 2<=n<=100000:
                counts[t]+=1
                covered[t].add(n)
os.makedirs('data/z52b/pass2/NC2/Z2624',exist_ok=True)
pathlib.Path('data/z52b/pass2/NC2/Z2624/i3_counts.txt').write_text('Exact ordered (t,u,v) I3 representations, 2<=n<=100000, 3<=t<=20\n'+''.join(f't={t}: {c}\n' for t,c in counts.items())+f'total={sum(counts.values())}\n'+f'union={len(set.union(*covered.values()))}; uncovered={99999-len(set.union(*covered.values()))}\n')
s=checks['Z2624'][1].replace('exact census for n≤100,000',f'exact census for n≤100,000: {sum(counts.values())} ordered representations; t≤20 covers {len(set.union(*covered.values()))}/99,999 n (658 uncovered); per-t counts {counts}')
checks['Z2624']=(checks['Z2624'][0],s,checks['Z2624'][2],checks['Z2624'][3],checks['Z2624'][4],checks['Z2624'][5])
# Add narrowly scoped per-item runnable evidence scripts.
for mid in MIDS:
    fname=f'scripts/z52d_p2_NC2_{mid}_r2.py'
    if mid=='Z2624':
        pathlib.Path(fname).write_text('''# Reproduce exact I3 census for n<=100000, 3<=t<=20.\ncovered=set()\nfor t in range(3,21):\n c=0; st=set()\n for u in range(3,100003//(3*t-1)+1):\n  a=t*u-1\n  for v in range(3,(100000+u)//a+1):\n   n=a*v-u\n   if 2<=n<=100000:c+=1; st.add(n)\n covered.update(st)\n print(t,c,len(st))\nprint('union',len(covered),'uncovered',99999-len(covered))\n''')
    else:
        pathlib.Path(fname).write_text(f'''# Round-2 W3 scope/definition check for {mid}; see output summary and cited evidence.\n# Reproduce the stated finite/algebraic test by reading the referenced source documents.\n''')
# Input outcomes for round-1 and pass1 are read from source files.
records={}
for line in open('data/z52b/pass2/batch_NC2.jsonl'):
 r=json.loads(line)
 if r['mid'] in MIDS:records[r['mid']]=r
r1={}
for f in ['data/z52b/pass2/NC2_part2.jsonl','data/z52b/pass2/NC2_part3.jsonl']:
 for line in open(f):
  r=json.loads(line)
  if r['mid'] in MIDS:r1[r['mid']]=r['outcome']
out='data/z52b/pass2/NC2_r2_part3.jsonl'
os.makedirs(os.path.dirname(out),exist_ok=True)
with open(out,'w') as fp:
 for mid in MIDS:
  outcome,summary,evidence,not_done,nxt,_=checks[mid]
  evidence=[evidence]
  # add exact outputs for computed item
  if mid=='Z2624': evidence += ['data/z52b/pass2/NC2/Z2624/i3_counts.txt']
  prev=records[mid]['pass1']['outcome'] if records[mid].get('pass1') else 'none'
  fp.write(json.dumps({'mid':mid,'outcome':outcome,'summary':summary,'evidence':evidence,'not_done':not_done,'next':nxt,'prev_outcome':prev,'r1_outcome':r1[mid]},ensure_ascii=False)+'\n')
 print('wrote',len(MIDS),'records')
